-- GenDB engine variant Q03-conjunct_permutation: template q03.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  l_orderkey,
  SUM(l_extendedprice * (
    1 - l_discount
  )) AS revenue,
  o_orderdate,
  o_shippriority
FROM customer, orders, lineitem
WHERE
  l_shipdate > $2
  AND o_orderdate < $2
  AND l_orderkey = o_orderkey
  AND c_custkey = o_custkey
  AND c_mktsegment = $1
GROUP BY
  l_orderkey,
  o_orderdate,
  o_shippriority
ORDER BY
  revenue DESC,
  o_orderdate
LIMIT 10
